do $test$
declare person uuid:=gen_random_uuid(); project uuid:=gen_random_uuid(); role_id uuid:=gen_random_uuid(); entry_id uuid:=gen_random_uuid(); token uuid:=gen_random_uuid(); label text:='Portrait été/face'; path text; photos jsonb; responses jsonb:='[{"question":"Question fictive","reponse":"oui","precision":"Précision fictive"}]'; initial_responses jsonb;
begin begin
 insert into public.projets(id,nom,owner_id) values(project,'Atomicité casting fictif','00000000-0000-4000-8000-00000000c0c0');
 insert into public.figurants(id,prenom,nom,date_naissance,ville) values(person,'Casting','Atomique fictif','1990-01-01','Avant');
 insert into public.casting_roles(id,projet_id,nom,nb_videos,photo_labels,questions,demande_bande_demo) values(role_id,project,'Rôle fictif',0,array[label],array['Question fictive'],true);
 insert into public.casting_entries(id,projet_id,figurant_id,role_id,request_token,statut) values(entry_id,project,person,role_id,token,'a_relancer');
 select reponses into initial_responses from public.casting_entries where id=entry_id;
 path:=person::text||'/casting-'||entry_id::text||'-Portrait%20%C3%A9t%C3%A9%2Fface-'||gen_random_uuid()::text||'.jpg';
 insert into storage.objects(bucket_id,name,metadata) values('figurant-photos',path,'{"size":500,"mimetype":"image/jpeg"}');
 photos:=jsonb_build_array(jsonb_build_object('label',label,'path',path));
 assert not has_function_privilege('anon','public.finaliser_casting_atomique(uuid,text[],jsonb,jsonb,text,jsonb)','EXECUTE'),'RPC finalisation publique';
 assert not has_function_privilege('authenticated','public.finaliser_casting_atomique(uuid,text[],jsonb,jsonb,text,jsonb)','EXECUTE'),'RPC finalisation staff générique';
 execute format('create function pg_temp.fail_casting_fixture() returns trigger language plpgsql as $guard$ begin if new.figurant_id=%L::uuid then raise exception using errcode=''ZX003'',message=''fixture panne notification''; end if; return new; end $guard$',person::text);
 create trigger fixture_casting_failure before insert on public.notifications for each row execute function pg_temp.fail_casting_fixture();
 set local role service_role;
 assert public.casting_path_component(label)='Portrait%20%C3%A9t%C3%A9%2Fface','Encodage de label différent du navigateur';
 begin perform public.finaliser_casting_atomique(token,'{}',photos,'{"ville":"Après"}','https://example.test/demo','[]'); raise exception using errcode='ZX002',message='Questions manquantes acceptées'; exception when check_violation then null; end;
 assert not exists(select 1 from public.figurant_photos where casting_entry_id=entry_id),'Photo ajoutée malgré refus';
 begin perform public.finaliser_casting_atomique(token,'{}',photos,'{"ville":"Après","taille_cm":180}','https://example.test/demo',responses); raise exception using errcode='ZX002',message='Panne ignorée'; exception when sqlstate 'ZX003' then null; end;
 assert not exists(select 1 from public.figurant_photos where casting_entry_id=entry_id),'Photo persistée malgré rollback';
 assert (select ville='Avant' and taille_cm is null from public.figurants where id=person),'Fiche modifiée malgré rollback';
 assert not exists(select 1 from public.figurant_liens where figurant_id=person),'Bande démo persistée malgré rollback';
 assert (select submitted_at is null and reponses is not distinct from initial_responses from public.casting_entries where id=entry_id),'Entrée modifiée malgré rollback';
 reset role;
 drop trigger fixture_casting_failure on public.notifications;
 set local role service_role;
 assert public.finaliser_casting_atomique(token,'{}',photos,'{"ville":"Après","taille_cm":180}','https://example.test/demo',responses),'Finalisation refusée';
 assert (select count(*)=1 from public.figurant_photos where casting_entry_id=entry_id),'Nombre de photos erroné';
 assert (select ville='Après' and taille_cm=180 from public.figurants where id=person),'Fiche non sauvegardée';
 assert exists(select 1 from public.figurant_liens where figurant_id=person and url='https://example.test/demo'),'Bande démo absente';
 assert (select submitted_at is not null and statut='a_relancer' and reponses=responses from public.casting_entries where id=entry_id),'Statut avancé régressé ou réponses absentes';
 assert (select count(*)=1 from public.notifications where figurant_id=person and projet_id=project),'Notification absente ou dupliquée';
 begin perform public.finaliser_casting_atomique(token,'{}',photos,'{"ville":"INTRUSION"}',null,responses); raise exception using errcode='ZX002',message='Deuxième finalisation acceptée'; exception when check_violation then null; end;
 assert (select ville='Après' from public.figurants where id=person),'Fiche modifiée après clôture';
 assert (select count(*)=1 from public.figurant_photos where casting_entry_id=entry_id),'Photo dupliquée après clôture';
 raise exception using errcode='ZX001',message='rollback fixtures';
 exception when sqlstate 'ZX001' then null; end;
end $test$;
